"""Explain reports, uninitialized use and bit shadow with beginner examples."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1785': ('문제가 생긴 물건의 이동 기록을 거꾸로 따라가요. 발견한 곳, 중간에 옮긴 곳, 처음 생긴 곳은 서로 다를 수 있어요.', 'KMSAN 보고서의 세 호출 기록과 바이트 범위를 읽습니다.', '사용 → 저장 → 생성의 세 칸을 그리고, 0~7번 여덟 바이트 중 4·5·6·7번에 표시하세요.', ['KMSAN 보고서는 준비되지 않은 값이 어디에서 사용됐는지 찾도록 도와줘요. stack trace는 그 시점에 함수들이 어떤 순서로 호출됐는지 보여 주는 목록이에요. 목록이 여러 개면 각 목록의 제목부터 읽어야 해요.', '고정 문서 예제의 첫 번째 호출 목록은 준비되지 않은 값을 사용한 위치예요. 문제가 드러난 곳이지만, 그 변수를 처음 만든 곳과 꼭 같은 것은 아니에요. 발견 위치와 발생 원인을 나누어 생각하세요.', '가운데의 Uninit was stored to memory at은 준비되지 않은 값이 메모리에 저장된 위치예요. 값을 다른 곳에 옮겼다고 그 값이 준비된 것으로 바뀌지는 않아요. 이 기록은 문제가 이동한 길을 찾는 단서예요.', '마지막 Local variable uninit created at은 지역 변수가 초기화되지 않은 채 만들어진 위치예요. 어떤 값을 넣어야 했는지 찾으려면 생성부터 사용까지의 코드 흐름도 살펴야 해요. 생성 위치만 보고 잘못된 줄 하나가 자동으로 확정되지는 않아요.', 'Bytes 4-7 of 8은 여덟 바이트 가운데 번호 4, 5, 6, 7이 준비되지 않았다는 뜻이에요. 번호는 0부터 시작하고 끝 번호 7도 포함해요. 따라서 개수는 7 - 4 + 1 = 4바이트예요.', '문서 예제 안의 5.16 버전 문자열은 예제 로그의 기록이에요. 우리가 고정 v6.12 문서를 읽었다고 지금 그 커널을 실행해 같은 로그를 만들었다는 뜻은 아니에요. 문서 예제, 함수 모델의 기록, 실제 실행 로그를 구분해서 읽으세요.'], [('공식 예제의 첫 번째 호출 목록은 어디를 보여 주나요?', ['반드시 변수를 처음 만든 위치만 보여 줘요', '준비되지 않은 값을 사용한 위치를 보여 줘요'], '정답은 두 번째예요. 생성 위치는 뒤의 별도 목록에서 설명해요. 같은 모양의 함수 목록이라도 무엇을 기록했는지 제목과 설명을 확인하세요.'), ('Bytes 4-7 of 8에서 준비되지 않은 바이트는 몇 개인가요?', ['4개예요', '3개예요'], '정답은 첫 번째예요. 4, 5, 6, 7을 직접 세면 네 개예요. 양끝 번호를 모두 포함하므로 7 - 4에 1을 더해야 해요.')]), 'os1786': ('값을 적지 않은 번호표로 서랍을 고르면 어느 서랍을 열지 믿을 수 없어요. 준비되지 않은 값이 무엇을 결정하는지 살펴보는 수업이에요.', '미초기화 값의 존재와 문제가 드러나는 사용 지점을 구별합니다.', 'if(v), array[v], 외부 전달 세 칸에 각각 실행할 길, 접근할 칸, 밖으로 보낼 내용을 적으세요.', ['초기화는 변수를 쓰기 전에 의도한 값을 넣는 일이에요. 변수를 만들었다는 것만으로 필요한 값을 넣었다고 볼 수는 없어요. KMSAN 문서는 그런 값이 어떤 용도로 사용될 때 보고하는지 설명해요.', 'if(v)는 v를 보고 어느 길로 실행할지 정해요. v가 준비되지 않았다면 프로그램의 선택에 믿을 만한 근거가 없는 셈이에요. 배열의 array[v]에서는 v가 접근할 칸 번호, 즉 index예요. 잘못된 번호는 잘못된 접근으로 이어질 수 있어요.', '*v처럼 포인터를 따라가는 경우에는 v가 찾아갈 주소를 정해요. 숫자를 계산하는 일과 메모리 위치를 결정하는 일의 영향을 구분해 보세요. 문서는 조건과 배열 번호·포인터 사용을 보고 대상의 예로 들어요.', '사용자 공간이나 장치로 준비되지 않은 메모리를 보내는 경우도 있어요. 사용자 공간은 일반 프로그램이 실행되는 영역이에요. 내용을 제대로 채우지 않고 밖으로 보내면 의도하지 않은 정보가 전달될 수 있어요.', '함수 인자와 반환값의 이른 검사는 CONFIG_KMSAN_CHECK_PARAM_RETVAL 설정과 관련돼요. 따라서 변수 선언만 보면 언제나 즉시 같은 경고가 난다고 외우지 마세요. 값의 생성, 전달, 사용 위치와 검사 설정을 함께 읽어요.', '연습에서는 실제 값을 넣지 않은 C 변수를 읽기보다 준비 상태를 별도 표에 표시해요. 예를 들어 실제 값은 0으로 정해 두고 모델의 shadow만 미준비로 놓아 흐름을 계산할 수 있어요. 이런 모델은 실제 C의 잘못된 읽기가 안전하다고 증명하는 것이 아니에요.'], [('array[v]에서 v는 무엇을 결정하나요?', ['변수 이름일 뿐 접근 위치에는 영향을 주지 않아요', '배열에서 접근할 칸 번호를 정해요'], '정답은 두 번째예요. 이 번호를 index라고 불러요. v의 준비 상태가 중요한 이유는 그 값이 실제 접근 위치를 고르기 때문이에요.'), ('원리를 공부하려면 실제 미초기화 C 값을 정상적인 숫자처럼 반복해서 읽어야 하나요?', ['아니요. 명시적인 준비 상태표와 원문 흐름으로 연습할 수 있어요', '네. 잘못된 읽기를 반복해야만 원리를 알 수 있어요'], '정답은 첫 번째예요. 따로 만든 shadow 모델에서 준비됨·미준비를 표시하면 흐름을 계산할 수 있어요. 실제 C 실행의 보장되지 않는 동작을 정상 결과로 삼을 필요가 없어요.')]), 'os1787': ('시험 답안의 숫자와 답안을 작성했는지 나타내는 체크 표시는 달라요. 숫자가 0이 아니어도 제대로 작성한 답안일 수 있어요.', '데이터 비트 값과 shadow의 준비 상태를 구별합니다.', '데이터 11111111 옆에 shadow 00000000을 적고 각각 내용과 준비 상태라고 표시하세요.', ['비트는 0 또는 1을 담는 작은 단위이고 8비트가 1바이트예요. KMSAN은 데이터 바이트에 대응하는 shadow 바이트로 준비 상태를 추적해요. shadow는 데이터의 복사본이 아니라 검사표예요.', 'shadow의 어느 비트가 1이면 대응하는 데이터 비트가 준비되지 않았다는 뜻이에요. shadow 비트가 0이면 그 비트에 미준비 표시가 없어요. 데이터 자체의 비트 값이 0인지 1인지와는 다른 질문이에요.', '정상적으로 상수 0xFF를 썼다고 해 봐요. 0x는 16진수 표기이고 FF는 이진수 11111111, 십진수 255예요. 데이터 비트는 모두 1이지만 준비된 상수를 썼으므로 shadow는 00000000이에요.', '반대로 메모리 내용이 우연히 숫자 0처럼 보인다고 초기화가 됐다는 뜻은 아니에요. 필요한 값을 의도한 경로로 썼는지에 관한 상태를 추적해야 해요. 데이터 값만 보고 shadow 값을 그대로 베끼면 이 차이를 놓쳐요.', 'poison은 shadow에 미준비 표시를 넣는 것이고, 모든 비트를 미준비로 표시하면 shadow 바이트가 FF예요. unpoison은 준비됨으로 표시해서 shadow를 00으로 만드는 것이에요. 실제 데이터를 FF나 00으로 채우라는 뜻과는 구별하세요.', '고정 문서는 바로 초기화되지 않은 스택 변수와 __GFP_ZERO 없이 받은 새 힙 메모리를 poison하는 원리를 설명해요. 스택 변수는 함수 실행에 딸린 변수이고 힙 메모리는 따로 할당받는 공간이에요. 실제 hook의 활성 상태와 예외 조건은 각 구현에서 함께 살펴야 해요.'], [('정상 상수 0xFF로 초기화한 한 바이트의 shadow는 무엇인가요?', ['데이터를 복사한 0xFF예요', '준비됨을 나타내는 0이에요'], '정답은 두 번째예요. 데이터는 255여도 준비된 값이에요. shadow는 숫자의 내용이 아니라 준비 상태를 나타내므로 0이 돼요.'), ('shadow의 한 비트가 1이라는 뜻은 무엇인가요?', ['대응 데이터 비트가 준비되지 않았다는 뜻이에요', '대응 데이터 비트의 실제 값이 반드시 1이라는 뜻이에요'], '정답은 첫 번째예요. 데이터 값과 검사 비트의 의미는 달라요. 검사표의 1은 미준비 상태를 나타내요.')]), 'os1788': ('두 스위치 중 하나만 켜져도 불이 켜지는 장치를 생각해 봐요. 한 스위치가 확실히 켜져 있으면 다른 스위치 상태를 몰라도 결과를 알 수 있어요.', '비트 OR에서 확실한 1이 결과를 결정하는 원리를 이해합니다.', '1 OR ?와 0 OR ?를 쓰고 ?에 0과 1을 각각 넣어 결과가 같은지 비교하세요.', ['비트 OR는 같은 자리의 두 비트 중 하나라도 1이면 결과가 1인 연산이에요. C에서는 |로 적어요. 0 | 0은 0이고, 0 | 1, 1 | 0, 1 | 1은 모두 1이에요. 각 자리를 따로 계산해요.', '모르는 비트를 ?로 표시해 볼게요. 확실한 1과 ?를 OR하면 ?가 0이든 1이든 결과는 1이에요. 따라서 결과를 알 수 있어요. 반면 확실한 0과 ?를 OR하면 ?에 따라 0이나 1이므로 여전히 몰라요.', '공식 문서의 32비트 모델에서 a는 준비된 0x000000FF예요. 아래쪽 8비트가 모두 1이고 위쪽 24비트가 모두 0이에요. b의 32비트는 모두 미준비로 표시되어 있어요. 이는 추적 원리를 설명하기 위한 상태 모델이에요.', 'c = a | b에서 아래쪽 8비트는 a의 확실한 1 때문에 결과가 모두 1로 정해져요. 이 부분은 미준비 표시가 사라져 shadow 비트가 0이에요. 결과 데이터 비트는 1, 결과 shadow 비트는 0이라는 차이를 기억하세요.', '위쪽 24비트에서는 a가 0이라 b를 알아야 결과를 알아요. 따라서 이 부분의 shadow는 계속 1이에요. 위쪽 24개가 1이고 아래쪽 8개가 0인 shadow를 16진수로 쓰면 0xFFFFFF00이에요.', 'F 한 글자는 1111 네 비트예요. F 여섯 글자는 24비트의 1, 00은 8비트의 0이에요. 이 계산은 미초기화 b를 실제 C로 읽어도 된다는 사용 허가가 아니에요. 종이의 ?와 명시적인 shadow로 결과의 알려진 부분을 계산하는 연습이에요.'], [('문서의 32비트 OR 예제에서 c의 shadow는 무엇인가요?', ['모든 비트가 미준비인 0xFFFFFFFF예요', '아래쪽 8비트만 준비된 0xFFFFFF00이에요'], '정답은 두 번째예요. 아래쪽은 확실한 1과 OR하므로 결과를 알아요. 위쪽은 확실한 0과 모르는 비트의 OR라 미준비 표시가 남아요.'), ('확실한 0과 모르는 비트 ?를 OR하면 결과를 확정할 수 있나요?', ['아니요. ?가 0인지 1인지에 따라 달라요', '네. 언제나 확실한 1이 돼요'], '정답은 첫 번째예요. 0 | 0은 0, 0 | 1은 1이에요. 두 가능한 결과가 다르므로 ?를 모르면 결과도 몰라요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_442.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
